const sumLPStorePaymentsBetween = `-- name: SumLPStorePaymentsBetween :one
SELECT COALESCE(SUM(-amount), 0)::float8 AS isk, COUNT(*)::bigint AS n
FROM ledger_journal
WHERE owner_kind = 'char' AND owner_id = $1 AND ref_type = 'lp_store'
  AND at > $2::timestamptz AND at <= $3::timestamptz
`

type SumLPStorePaymentsBetweenParams struct {
	OwnerID int64     `json:"owner_id"`
	FromAt  time.Time `json:"from_at"`
	ToAt    time.Time `json:"to_at"`
}

type SumLPStorePaymentsBetweenRow struct {
	Isk float64 `json:"isk"`
	N   int64   `json:"n"`
}

// The journal's LP store payments inside a purchase's bracket.
func (q *Queries) SumLPStorePaymentsBetween(ctx context.Context, arg SumLPStorePaymentsBetweenParams) (SumLPStorePaymentsBetweenRow, error) {
	row := q.db.QueryRowContext(ctx, sumLPStorePaymentsBetween, arg.OwnerID, arg.FromAt, arg.ToAt)
	var i SumLPStorePaymentsBetweenRow
	err := row.Scan(&i.Isk, &i.N)
	return i, err
}

const sumProfitLPDelta = `-- name: SumProfitLPDelta :one
SELECT COALESCE(SUM(lp_delta), 0)::bigint FROM profit_daily
WHERE owner_kind = $1 AND owner_id = ANY($2::bigint[])
  AND day >= $3::text AND activity = 'lp'
`

type SumProfitLPDeltaParams struct {
	OwnerKind string  `json:"owner_kind"`
	OwnerIds  []int64 `json:"owner_ids"`
	FromDay   string  `json:"from_day"`
}

// Net LP over a span, for profit at the player's ISK per LP.
func (q *Queries) SumProfitLPDelta(ctx context.Context, arg SumProfitLPDeltaParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumProfitLPDelta, arg.OwnerKind, pq.Array(arg.OwnerIds), arg.FromDay)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
